def choose_move(observation):
    gx, gy = observation['grid_width'], observation['grid_height']
    my_x, my_y = observation['self_position']
    opponent_x, opponent_y = observation['opponent_position']
    obstacles = set((o['x'], o['y']) for o in observation['obstacles'])
    resources = observation['resources']
    remaining = observation['remaining_resource_count']
    self_path = set(observation['self_path'])
    opponent_path = set(observation['opponent_path'])

    def hit_wall_or_obstacle(x, y):
        return x < 0 or y < 0 or x >= gx or y >= gy or (x, y) in obstacles

    def move_towards(target_x, target_y):
        dx = dy = 0
        if my_x < target_x:
            dx = 1
        elif my_x > target_x:
            dx = -1
        if my_y < target_y:
            dy = 1
        elif my_y > target_y:
            dy = -1
        return dx, dy

    # Prioritize collecting resources if available
    if resources:
        closest_res = min(resources, key=lambda r: abs(r['x'] - my_x) + abs(r['y'] - my_y))
        dx, dy = move_towards(closest_res['x'], closest_res['y'])
        if not hit_wall_or_obstacle(my_x + dx, my_y + dy):
            return [dx, dy]

    # Otherwise, move towards opponent to block or pursue
    dx, dy = move_towards(opponent_x, opponent_y)
    if not hit_wall_or_obstacle(my_x + dx, my_y + dy):
        return [dx, dy]

    # If blocked, try straight directions
    for nx, ny in [(1,0), (-1,0), (0,1), (0,-1)]:
        nx, ny = my_x + nx, my_y + ny
        if not hit_wall_or_obstacle(nx, ny):
            return [nx - my_x, ny - my_y]

    # No move possible; stay in place
    return [0, 0]
